--
-- Name: apply_lms_course_release(uuid, jsonb, jsonb, jsonb, uuid[], uuid[], jsonb, text, jsonb, text, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_lms_course_release(p_course_id uuid, p_course jsonb, p_modules jsonb, p_lessons jsonb, p_remove_lesson_ids uuid[], p_remove_module_ids uuid[], p_final_values jsonb, p_kind text, p_content jsonb, p_content_hash text, p_created_by uuid DEFAULT NULL::uuid, p_label text DEFAULT NULL::text, p_source_revision_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, revision_number bigint, created_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_exists boolean;
  v_revision record;
BEGIN
  SELECT true INTO v_exists FROM public.lms_courses c WHERE c.id = p_course_id;

  IF v_exists IS NULL THEN
    PERFORM public.cw_apply_row_set('public.lms_courses'::regclass, jsonb_build_array(p_course));
  ELSE
    PERFORM public.cw_patch_lms_course(p_course_id, p_course);
  END IF;

  PERFORM public.cw_apply_row_set('public.lms_modules'::regclass, p_modules);
  PERFORM public.cw_apply_row_set('public.lms_lessons'::regclass, p_lessons);

  IF p_remove_lesson_ids IS NOT NULL AND array_length(p_remove_lesson_ids, 1) > 0 THEN
    DELETE FROM public.lms_lessons l WHERE l.id = ANY(p_remove_lesson_ids);
  END IF;

  IF p_remove_module_ids IS NOT NULL AND array_length(p_remove_module_ids, 1) > 0 THEN
    DELETE FROM public.lms_modules m WHERE m.id = ANY(p_remove_module_ids);
  END IF;

  PERFORM public.cw_patch_lms_course(p_course_id, p_final_values);

  SELECT * INTO v_revision FROM public.create_lms_course_revision(
    p_course_id, p_kind, p_content, p_content_hash,
    p_created_by, p_label, NULL, p_source_revision_id
  );

  -- Только релиз. `restored` кладёт документ в pending и живого выпуска не
  -- трогает; `review_submitted` тем более.
  IF p_kind = 'published' THEN
    UPDATE public.lms_courses c
    SET published_revision_id = v_revision.id
    WHERE c.id = p_course_id;
  END IF;

  RETURN QUERY SELECT v_revision.id, v_revision.revision_number, v_revision.created_at;
END;
$$;


--
-- Name: check_rate_limit(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_rate_limit(p_key text, p_max integer, p_window_seconds integer) RETURNS TABLE(allowed boolean, current_count integer, retry_after integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_window_start timestamptz;
  v_count integer;
begin
  -- align to fixed bucket boundary
  v_window_start := to_timestamp(
    floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds
  );

  insert into public.rate_limits as rl (key, window_start, count)
  values (p_key, v_window_start, 1)
  on conflict (key, window_start)
  do update set count = rl.count + 1
  returning rl.count into v_count;

  allowed := v_count <= p_max;
  current_count := v_count;
  retry_after := case
    when v_count <= p_max then 0
    else ceil(extract(epoch from (
      v_window_start + make_interval(secs => p_window_seconds) - now()
    )))::int
  end;

  -- opportunistic prune of old buckets (~1% of calls) to bound table growth
  if random() < 0.01 then
    delete from public.rate_limits
    where window_start < now() - interval '1 hour';
  end if;

  return next;
end;
$$;


--
-- Name: checkpoint_lms_course_autosave(uuid, jsonb, text, uuid, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_lms_course_autosave(p_course_id uuid, p_content jsonb, p_content_hash text, p_created_by uuid DEFAULT NULL::uuid, p_min_interval interval DEFAULT '00:10:00'::interval) RETURNS TABLE(id uuid, revision_number bigint, created_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_last_hash text;
  v_last_at timestamptz;
BEGIN
  SELECT r.content_hash, r.created_at
    INTO v_last_hash, v_last_at
  FROM public.lms_course_revisions r
  WHERE r.course_id = p_course_id
  ORDER BY r.revision_number DESC
  LIMIT 1;

  -- Нечего фиксировать: документ тот же, что в последней записи журнала.
  -- Сравнение с записью ЛЮБОГО вида намеренно — автор мог только что сохранить
  -- версию вручную или пройти публикацию, и дублировать её содержимое
  -- автоматической точкой незачем.
  IF v_last_hash = p_content_hash THEN
    RETURN;
  END IF;

  -- Слишком рано. Тоже относительно записи любого вида: журнал не пополняется
  -- автоматическими точками чаще, чем раз в интервал, независимо от того, что
  -- было последним.
  IF v_last_at IS NOT NULL AND v_last_at > now() - p_min_interval THEN
    RETURN;
  END IF;

  RETURN QUERY SELECT * FROM public.create_lms_course_revision(
    p_course_id, 'autosave_checkpoint', p_content, p_content_hash,
    p_created_by, NULL, NULL, NULL
  );
END;
$$;


--
-- Name: create_lms_course_revision(uuid, text, jsonb, text, uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_lms_course_revision(p_course_id uuid, p_kind text, p_content jsonb, p_content_hash text, p_created_by uuid DEFAULT NULL::uuid, p_label text DEFAULT NULL::text, p_parent_revision_id uuid DEFAULT NULL::uuid, p_source_revision_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, revision_number bigint, created_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_revision_number bigint;
  v_parent uuid;
BEGIN
  UPDATE public.lms_courses
  SET revision_seq = revision_seq + 1
  WHERE public.lms_courses.id = p_course_id
  RETURNING revision_seq INTO v_revision_number;

  IF v_revision_number IS NULL THEN
    RAISE EXCEPTION 'lms_course_not_found';
  END IF;

  -- Предыдущая запись журнала этого курса. Читается ПОСЛЕ того, как счётчик
  -- уже занят этой транзакцией, поэтому две параллельные записи не назовут
  -- родителем одну и ту же запись, разойдясь в разные ветки молча.
  v_parent := p_parent_revision_id;
  IF v_parent IS NULL THEN
    SELECT r.id INTO v_parent
    FROM public.lms_course_revisions r
    WHERE r.course_id = p_course_id
    ORDER BY r.revision_number DESC
    LIMIT 1;
  END IF;

  RETURN QUERY
  INSERT INTO public.lms_course_revisions (
    course_id, revision_number, kind, content, content_hash, label,
    created_by, parent_revision_id, source_revision_id
  ) VALUES (
    p_course_id, v_revision_number, p_kind, p_content, p_content_hash,
    NULLIF(btrim(p_label), ''), p_created_by, v_parent,
    p_source_revision_id
  )
  RETURNING lms_course_revisions.id, lms_course_revisions.revision_number,
    lms_course_revisions.created_at;
END;
$$;


--
-- Name: create_lms_course_revision_once(uuid, text, jsonb, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_lms_course_revision_once(p_course_id uuid, p_kind text, p_content jsonb, p_content_hash text, p_created_by uuid DEFAULT NULL::uuid, p_label text DEFAULT NULL::text) RETURNS TABLE(id uuid, revision_number bigint, created_at timestamp with time zone, created boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_existing public.lms_course_revisions%ROWTYPE;
BEGIN
  SELECT * INTO v_existing
  FROM public.lms_course_revisions r
  WHERE r.course_id = p_course_id
  ORDER BY r.revision_number DESC
  LIMIT 1;

  IF v_existing.id IS NOT NULL AND v_existing.content_hash = p_content_hash THEN
    RETURN QUERY SELECT v_existing.id, v_existing.revision_number, v_existing.created_at, false;
    RETURN;
  END IF;

  RETURN QUERY
  SELECT c.id, c.revision_number, c.created_at, true
  FROM public.create_lms_course_revision(
    p_course_id, p_kind, p_content, p_content_hash, p_created_by, p_label, NULL, NULL
  ) c;
END;
$$;


--
-- Name: cron_call_endpoint(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cron_call_endpoint(path text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  base   text;
  secret text;
BEGIN
  SELECT decrypted_secret INTO base
    FROM vault.decrypted_secrets WHERE name = 'cron_base_url';
  SELECT decrypted_secret INTO secret
    FROM vault.decrypted_secrets WHERE name = 'cron_secret';

  IF base IS NULL OR secret IS NULL THEN
    -- Loud, not silent. A scheduler that quietly stops calling anything is the
    -- failure mode this whole change is meant to remove, not introduce.
    RAISE EXCEPTION 'cron_call_endpoint: vault secrets cron_base_url/cron_secret are not set';
  END IF;

  RETURN net.http_get(
    url     := base || path,
    headers := jsonb_build_object('Authorization', 'Bearer ' || secret),
    -- Longer than a fast endpoint needs and shorter than the function's own
    -- ceiling: process-jobs can legitimately spend a while draining a backlog.
    timeout_milliseconds := 60000
  );
END;
$$;


--
-- Name: cw_apply_row_set(regclass, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cw_apply_row_set(p_table regclass, p_rows jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE
  v_cols text;
  v_set text;
BEGIN
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RETURN;
  END IF;

  -- Only keys that are real, live columns of the target table, in catalog
  -- order. A payload key that is not a column is ignored rather than raising:
  -- the alternative is that adding a field to the typed Course document breaks
  -- every write until the database catches up.
  SELECT string_agg(quote_ident(a.attname), ', ' ORDER BY a.attnum),
         string_agg(
           CASE WHEN a.attname = 'id' THEN NULL
                ELSE quote_ident(a.attname) || ' = EXCLUDED.' || quote_ident(a.attname) END,
           ', ' ORDER BY a.attnum)
    INTO v_cols, v_set
  FROM pg_catalog.pg_attribute a
  WHERE a.attrelid = p_table
    AND a.attnum > 0
    AND NOT a.attisdropped
    AND p_rows -> 0 ? a.attname;

  IF v_cols IS NULL THEN
    RAISE EXCEPTION 'cw_apply_row_set_no_columns:%', p_table;
  END IF;

  IF v_set IS NULL THEN
    EXECUTE format(
      'INSERT INTO %s (%s) SELECT %s FROM jsonb_populate_recordset(null::%s, $1) ON CONFLICT (id) DO NOTHING',
      p_table, v_cols, v_cols, p_table
    ) USING p_rows;
  ELSE
    EXECUTE format(
      'INSERT INTO %s (%s) SELECT %s FROM jsonb_populate_recordset(null::%s, $1) ON CONFLICT (id) DO UPDATE SET %s',
      p_table, v_cols, v_cols, p_table, v_set
    ) USING p_rows;
  END IF;
END;
$_$;


--
-- Name: cw_patch_lms_course(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cw_patch_lms_course(p_course_id uuid, p_values jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE
  v_cols text;
BEGIN
  IF p_values IS NULL OR p_values = '{}'::jsonb THEN
    RETURN;
  END IF;

  SELECT string_agg(quote_ident(a.attname), ', ' ORDER BY a.attnum)
    INTO v_cols
  FROM pg_catalog.pg_attribute a
  WHERE a.attrelid = 'public.lms_courses'::regclass
    AND a.attnum > 0
    AND NOT a.attisdropped
    AND a.attname <> 'id'
    AND p_values ? a.attname;

  IF v_cols IS NULL THEN
    RETURN;
  END IF;

  EXECUTE format(
    'UPDATE public.lms_courses SET (%s) = (SELECT %s FROM jsonb_populate_record(null::public.lms_courses, $1)) WHERE id = $2',
    v_cols, v_cols
  ) USING p_values, p_course_id;
END;
$_$;


