    model text,
    status text DEFAULT 'running'::text NOT NULL,
    input_tokens integer DEFAULT 0 NOT NULL,
    output_tokens integer DEFAULT 0 NOT NULL,
    error text,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    CONSTRAINT agent_runs_contour_check CHECK ((contour = ANY (ARRAY['builder'::text, 'assistant'::text]))),
    CONSTRAINT agent_runs_input_tokens_check CHECK ((input_tokens >= 0)),
    CONSTRAINT agent_runs_output_tokens_check CHECK ((output_tokens >= 0)),
    CONSTRAINT agent_runs_status_check CHECK ((status = ANY (ARRAY['running'::text, 'completed'::text, 'failed'::text, 'refused'::text, 'aborted'::text])))
);


