    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT lms_annotations_anchor CHECK ((((kind = 'bookmark'::text) AND (block_id IS NULL) AND (start_offset IS NULL) AND (end_offset IS NULL) AND (quote IS NULL)) OR ((kind = 'highlight'::text) AND (block_id IS NOT NULL) AND (start_offset IS NOT NULL) AND (end_offset IS NOT NULL) AND (end_offset > start_offset) AND (quote IS NOT NULL)))),
    CONSTRAINT lms_annotations_course_version_check CHECK ((course_version > 0)),
    CONSTRAINT lms_annotations_end_offset_check CHECK (((end_offset IS NULL) OR (end_offset >= 0))),
    CONSTRAINT lms_annotations_kind_check CHECK ((kind = ANY (ARRAY['bookmark'::text, 'highlight'::text]))),
    CONSTRAINT lms_annotations_start_offset_check CHECK (((start_offset IS NULL) OR (start_offset >= 0)))
);


