--
-- Name: mv_funnel_daily; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_funnel_daily AS
 WITH date_series AS (
         SELECT (generate_series(((( SELECT COALESCE(min(leads.created_at), (now() - '30 days'::interval)) AS "coalesce"
                   FROM public.leads))::date)::timestamp with time zone, ((now())::date)::timestamp with time zone, '1 day'::interval))::date AS report_date
        ), leads_daily AS (
         SELECT (leads.created_at)::date AS record_date,
            count(DISTINCT leads.id) AS total_leads,
            count(DISTINCT leads.phone) AS unique_phones,
            count(DISTINCT leads.email) AS unique_emails
           FROM public.leads
          GROUP BY ((leads.created_at)::date)
        ), orders_daily AS (
         SELECT (orders.created_at)::date AS record_date,
            count(DISTINCT orders.id) AS total_orders,
            count(DISTINCT orders.id) FILTER (WHERE (orders.status = ANY (ARRAY['paid'::text, 'completed'::text]))) AS paid_orders,
            sum(COALESCE(orders.amount, (0)::numeric)) FILTER (WHERE (orders.status = ANY (ARRAY['paid'::text, 'completed'::text]))) AS revenue
           FROM public.orders
          GROUP BY ((orders.created_at)::date)
        )
 SELECT ds.report_date AS date,
    COALESCE(l.total_leads, (0)::bigint) AS leads_count,
    COALESCE(l.unique_phones, (0)::bigint) AS unique_lead_phones,
    COALESCE(o.total_orders, (0)::bigint) AS orders_created,
    COALESCE(o.paid_orders, (0)::bigint) AS orders_paid,
    COALESCE(o.revenue, (0)::numeric) AS total_revenue,
        CASE
            WHEN (COALESCE(l.total_leads, (0)::bigint) > 0) THEN round((((COALESCE(o.paid_orders, (0)::bigint))::numeric / (l.total_leads)::numeric) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS conversion_rate_percent
   FROM ((date_series ds
     LEFT JOIN leads_daily l ON ((l.record_date = ds.report_date)))
     LEFT JOIN orders_daily o ON ((o.record_date = ds.report_date)))
  ORDER BY ds.report_date DESC
  WITH NO DATA;


--
-- Name: mv_quality_gaps; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_quality_gaps AS
 SELECT (now())::date AS snapshot_date,
    count(*) FILTER (WHERE ((status = ANY (ARRAY['paid'::text, 'completed'::text])) AND ((fbc IS NULL) OR (fbc = ''::text)))) AS paid_missing_fbc,
    count(*) FILTER (WHERE ((status = ANY (ARRAY['paid'::text, 'completed'::text])) AND ((fbclid IS NULL) OR (fbclid = ''::text)))) AS paid_missing_fbclid,
    count(*) FILTER (WHERE ((status = ANY (ARRAY['paid'::text, 'completed'::text])) AND ((fbp IS NULL) OR (fbp = ''::text)))) AS paid_missing_fbp,
    count(*) FILTER (WHERE ((status = ANY (ARRAY['paid'::text, 'completed'::text])) AND ((page_url IS NULL) OR (page_url = ''::text)))) AS paid_missing_page_url,
    count(*) FILTER (WHERE ((status = ANY (ARRAY['paid'::text, 'completed'::text])) AND ((client_ip IS NULL) OR (client_ip = ''::text)))) AS paid_missing_client_ip,
    count(*) FILTER (WHERE ((status = ANY (ARRAY['paid'::text, 'completed'::text])) AND ((client_ua IS NULL) OR (client_ua = ''::text)))) AS paid_missing_client_ua
   FROM public.orders o
  WITH NO DATA;


--
-- Name: mv_revenue_by_campaign; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_revenue_by_campaign AS
 SELECT
        CASE
            WHEN (NULLIF(TRIM(BOTH FROM campaign), ''::text) IS NOT NULL) THEN TRIM(BOTH FROM campaign)
            WHEN ((NULLIF(TRIM(BOTH FROM fbclid), ''::text) IS NOT NULL) OR (NULLIF(TRIM(BOTH FROM fbp), ''::text) IS NOT NULL)) THEN 'meta (no utm_campaign)'::text
            ELSE 'organic/direct'::text
        END AS source_campaign,
    count(id) AS total_orders,
    count(id) FILTER (WHERE (status = ANY (ARRAY['paid'::text, 'completed'::text]))) AS paid_orders,
    sum(COALESCE(amount, (0)::numeric)) FILTER (WHERE (status = ANY (ARRAY['paid'::text, 'completed'::text]))) AS total_revenue
   FROM public.orders
  GROUP BY
        CASE
            WHEN (NULLIF(TRIM(BOTH FROM campaign), ''::text) IS NOT NULL) THEN TRIM(BOTH FROM campaign)
            WHEN ((NULLIF(TRIM(BOTH FROM fbclid), ''::text) IS NOT NULL) OR (NULLIF(TRIM(BOTH FROM fbp), ''::text) IS NOT NULL)) THEN 'meta (no utm_campaign)'::text
            ELSE 'organic/direct'::text
        END
  ORDER BY (sum(COALESCE(amount, (0)::numeric)) FILTER (WHERE (status = ANY (ARRAY['paid'::text, 'completed'::text])))) DESC NULLS LAST
  WITH NO DATA;


