    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    CONSTRAINT personal_offer_tokens_amount_check CHECK ((amount > 0)),
    CONSTRAINT personal_offer_tokens_old_amount_check CHECK (((old_amount IS NULL) OR (old_amount > 0))),
    CONSTRAINT personal_offer_tokens_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'expired'::text, 'consumed'::text, 'cancelled'::text])))
);


