    auth_user_id uuid NOT NULL,
    email text,
    full_name text,
    avatar_url text,
    provider text,
    marketing_opt_in boolean DEFAULT false NOT NULL,
    onboarding_state text DEFAULT 'new'::text NOT NULL,
    last_sign_in_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    timezone text DEFAULT 'Europe/Kyiv'::text NOT NULL,
    locale text DEFAULT 'uk'::text NOT NULL,
    notification_channels text[] DEFAULT ARRAY['telegram'::text] NOT NULL,
    CONSTRAINT platform_users_onboarding_state_check CHECK ((onboarding_state = ANY (ARRAY['new'::text, 'profile_completed'::text, 'test_completed'::text, 'active'::text])))
);


--
-- Name: product_offers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.product_offers (
    code text NOT NULL,
    amount integer,
    list_amount integer,
    currency text DEFAULT 'UAH'::text NOT NULL,
    kind text DEFAULT 'checkout'::text NOT NULL,
    pixel_content_name text,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT product_offers_amount_positive CHECK (((amount IS NULL) OR (amount > 0))),
    CONSTRAINT product_offers_kind_known CHECK ((kind = ANY (ARRAY['checkout'::text, 'lead'::text]))),
    CONSTRAINT product_offers_list_above_amount CHECK (((list_amount IS NULL) OR ((amount IS NOT NULL) AND (list_amount > amount))))
);


