    attempt_id uuid NOT NULL,
    question_id uuid NOT NULL,
    option_id uuid NOT NULL,
    mapped_dosha text NOT NULL,
    answer_order integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT quiz_answers_answer_order_check CHECK ((answer_order > 0)),
    CONSTRAINT quiz_answers_mapped_dosha_check CHECK ((mapped_dosha = ANY (ARRAY['vata'::text, 'pitta'::text, 'kapha'::text])))
);


--
-- Name: test_attempts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.test_attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid,
    test_id uuid NOT NULL,
    session_id text NOT NULL,
    source text,
    status text DEFAULT 'started'::text NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    last_activity_at timestamp with time zone DEFAULT now() NOT NULL,
    current_question_index integer DEFAULT 0 NOT NULL,
    score_vata integer DEFAULT 0 NOT NULL,
    score_pitta integer DEFAULT 0 NOT NULL,
    score_kapha integer DEFAULT 0 NOT NULL,
    result_type public.dosha_result_type,
    result_payload_json jsonb,
    reminder_sent_count integer DEFAULT 0 NOT NULL,
    version text DEFAULT 'v1'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT quiz_attempts_current_question_index_check CHECK ((current_question_index >= 0)),
    CONSTRAINT quiz_attempts_reminder_sent_count_check CHECK ((reminder_sent_count >= 0)),
    CONSTRAINT quiz_attempts_score_kapha_check CHECK ((score_kapha >= 0)),
    CONSTRAINT quiz_attempts_score_pitta_check CHECK ((score_pitta >= 0)),
    CONSTRAINT quiz_attempts_score_vata_check CHECK ((score_vata >= 0)),
    CONSTRAINT quiz_attempts_status_check CHECK ((status = ANY (ARRAY['started'::text, 'completed'::text, 'abandoned'::text])))
);


