    CONSTRAINT quiz_options_mapped_dosha_check CHECK ((mapped_dosha = ANY (ARRAY['vata'::text, 'pitta'::text, 'kapha'::text]))),
    CONSTRAINT quiz_options_option_order_check CHECK ((option_order > 0))
);


