);


--
-- Name: v_user_latest_test_attempts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_user_latest_test_attempts WITH (security_invoker='on') AS
 SELECT DISTINCT ON (user_id, test_id) user_id,
    test_id,
    id AS attempt_id,
    result_type,
    score_vata,
    score_pitta,
    score_kapha,
    completed_at,
    version,
    created_at
   FROM public.test_attempts ta
  WHERE ((user_id IS NOT NULL) AND (status = 'completed'::text) AND (result_type IS NOT NULL))
  ORDER BY user_id, test_id, completed_at DESC NULLS LAST, created_at DESC;


--
-- Name: v_user_dosha_test_profile; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_user_dosha_test_profile WITH (security_invoker='on') AS
 SELECT v.user_id,
    v.test_id,
    td.slug AS test_slug,
    v.attempt_id,
    v.result_type,
    v.score_vata,
    v.score_pitta,
    v.score_kapha,
    v.completed_at,
    v.version
   FROM (public.v_user_latest_test_attempts v
     JOIN public.test_definitions td ON ((td.id = v.test_id)))
  WHERE (td.slug = 'dosha-test'::text);


